          (i) => i.id !== item.id && parsed.parentId !== item.id
        );
        if (validItems.length === 0) return;

        onDrop(validItems, parsed.parentId);
      } catch {
        // Invalid drag data, ignore
      }
    },
    [item, onDrop, onExternalFileDrop]
  );
  ```
  - Lines 346–348: Handlers wired only for folders
  - Calls `onDrop(validItems, sourceParentId)` for batch or single items

**onDrop Handler (FileList → useFileBrowserActions):**
- **FileList.tsx** (lines 221–225):
  ```typescript
  onDrop={
    onDropOnFolder && item.type === 'folder'
      ? (dragItems, sourceParentId) =>
          onDropOnFolder(dragItems, sourceParentId, item.id)
      : undefined
  }
  ```

**useFileBrowserActions.handleDropOnFolder:**
- **useFileBrowserActions.ts** (lines 349–367):
  ```typescript
  const handleDropOnFolder = useCallback(
    async (
      items: Array<{ id: string; type: 'file' | 'folder' }>,
      sourceParentId: string,
      destFolderId: string
    ) => {
      try {
        if (items.length === 1) {
          await moveItem(items[0].id, items[0].type, sourceParentId, destFolderId);
        } else {
          await moveItems(items, sourceParentId, destFolderId);
          clearSelection();
        }
      } catch (err) {
        logger.error('[FileBrowser] Move failed:', err);
      }
    },
    [moveItem, moveItems, clearSelection]
  );
  ```
  - **Single item:** calls `moveItem()` directly
  - **Multiple items:** calls `moveItems()` and clears selection

**Breadcrumbs Drop Target (Optional):**
- **Breadcrumbs.tsx** (lines 112–151): Also a drop target via `handleDrop()` → `onDrop()` callback
- Wired in FileBrowser.tsx line 132: `onDrop={actions.handleDropOnFolder}`

---

### **4. SDK SINGLE-ITEM moveItem**

**Location:** `/Users/myankelev/Code/random/cipher-box/packages/sdk/src/client.ts` (lines 702–804)

```typescript
async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> {
  return this.withOperation('moveItem', async () => {
    // 1. Fetch both folder metadata
    const source = await this.requireFolder(sourceIpnsName, 'Source folder');
    const dest = await this.requireFolder(destIpnsName, 'Destination folder');

    // 2. Compute updated children
    const { updatedSourceChildren, updatedDestChildren, movedItem } = sdkCore.moveItem({
      sourceChildren: source.children,
      destChildren: dest.children,
      childId,
    });

    // 3. Publish destination first (add-before-remove safety)
    const destResult = await sdkCore.updateFolderMetadataAndPublish({ ... });

    // 4. Re-encrypt file metadata (if file) from source.folderKey → dest.folderKey
    if (movedItem.type === 'file') {
      // unwrap, re-encrypt via reencryptFileMetadataForFolderChange, clear key
    }

    // 5. Publish source (remove)
    const sourceResult = await sdkCore.updateFolderMetadataAndPublish({ ... });

    // 6. Update internal state + emit folder:updated for both folders
  });
}
```

---

### **5. SHARED-FOLDER IMPLEMENTATIONS (CURRENT STATE)**

**useSharedWriteOps.ts** (lines 1–189):
- **Available methods:**
  - `uploadFileHandler` (line 77)
  - `createFolderHandler` (line 94)
  - `renameItemHandler` (line 106)
  - `updateSharedFileHandler` (line 123)
  - `deleteItemHandler` (line 173)
  - **NO MOVE METHOD**

**SharedFileBrowser.tsx** (lines 62–730):
- **Selection state:** ABSENT — no multi-select implementation
- **Batch move:** NOT IMPLEMENTED
- **Drag-and-drop (internal move):** NOT IMPLEMENTED
  - Only drag-and-drop upload (external files) is supported (lines 318–333)
  - SharedFolderRow: no drag/drop handlers for internal moves
- **Single-item move context menu:** NOT WIRED

**SDK Shared Folder Methods (client.ts):**
- `uploadToSharedFolder` (line 2110)
- `createSharedSubfolder` (line 2127)
- `renameInSharedFolder` (line 2141)
- `deleteFromSharedFolder` (line 2158)
- `updateSharedFile` (line 2183)
- `refreshSharedFolder` (line 2239)
- **NO moveInSharedFolder method in SDK**

---

### **6. ASSESSMENT: NET NEW WORK FOR SHARED FOLDER BATCH + DRAG-MOVE**

| Component | Private-Vault | Shared-Folder | Reusable? | Effort |
|-----------|---------------|---------------|-----------|--------|
| **Selection state** | ✓ `selectedIds` Set in useFileBrowserActions | ✗ Absent | Partial (copy pattern, rename hook) | LOW |
| **Batch move dialog state** | ✓ `batchMoveDialog` in useFileBrowserActions | ✗ Absent | Direct copy | MINIMAL |
| **MoveDialog component** | ✓ Flexible (item + items props) | ✗ Not used | Full reuse if mounted | MINIMAL |
| **Batch move handler** | ✓ `handleBatchMoveClick`, `handleBatchMoveConfirm` | ✗ Absent | Adapted copy (different write op hook) | LOW |
| **Drag source** | ✓ FileListItem.handleDragStart + multi-select payload | ✗ SharedFolderRow has no drag | Copy with SharedFolderRow integration | LOW |
| **Drop handler** | ✓ FileListItem.handleDrop + folder target logic | ✗ SharedFolderRow has no drop | Copy with SharedFolderRow integration | LOW |
| **useFileBrowserActions flow** | ✓ handleDropOnFolder → moveItem/moveItems | ✗ No equivalent hook | Create `useSharedFileBrowserActions` mirror | MEDIUM |
| **SDK moveInSharedFolder** | ✗ Not needed (uses own vault moveItem) | ✗ **MUST CREATE** | N/A (net new) | **HIGH** |
| **SDK batch loop** | ✓ Loops moveItem in web layer (useFolderMutations) | ✓ Mirror approach possible | Use same pattern | MINIMAL |

---

### **KEY FINDINGS**

1. **Batch move is a web-layer pattern**, not SDK: `useFolderMutations.handleMoveItems` loops `client.moveItem()` sequentially with validation.

2. **MoveDialog already supports batch** (lines 20–21, 176–179): just pass `items` prop, it auto-adapts UI.

3. **Drag-and-drop payload is smart**: multi-select detection in FileListItem.handleDragStart includes all selected items if the dragged item is in the selection.

4. **No dedicated SDK batch move method exists** for either vault or shared folders — both would loop single-item calls.

5. **Shared-folder equivalents are missing entirely**:
   - No selection state in SharedFileBrowser
   - No drag/drop for internal moves (only upload)
   - No `moveInSharedFolder` SDK method
   - useSharedWriteOps needs a `moveInSharedFolder` handler

6. **Reusability**:
   - **MoveDialog**: Direct reuse (component is generic)
   - **Selection + batch handlers**: Copy pattern from FileBrowser side, adapt to shared context
   - **Drag/drop**: Copy FileListItem logic, integrate into SharedFolderRow
   - **SDK moveInSharedFolder**: New implementation (similar architecture to moveItem but for shared context)
   - **useSharedWriteOps**: Add new handler following existing pattern (runWrite wrapper)

---

### **RECOMMENDED ROLLOUT ORDER**

1. **Create SDK `moveInSharedFolder(shareId, { itemId, destFolderId })`** ← must exist before web layer can call it
2. **Add `moveInSharedFolder` to useSharedWriteOps** following the existing `renameInSharedFolder` pattern
3. **Add selection state to SharedFileBrowser** (copy useFileBrowserActions selection logic)
4. **Wire batch move dialog + handlers** in SharedFileBrowser (minimal copy from FileBrowser)
5. **Add drag/drop to SharedFolderRow** (copy FileListItem logic, reuse JSON payload format)
6. **Mount MoveDialog in SharedFileBrowser** (use existing component)

