3	/**
4	 * Page object for SharedMoveDialog component.
5	 *
6	 * The SharedMoveDialog loads the shared subtree via enumerateSharedSubtree and
7	 * renders destination folder rows with role="button". Read-only or current-folder
8	 * rows are disabled (aria-disabled="true", class "move-dialog-folder-item--disabled").
9	 *
10	 * Mirrors the shape of MoveDialogPage for the private-vault dialog.
11	 */
12	export class SharedMoveDialogPage {
13	  constructor(private readonly page: Page) {}
14	
15	  /**
16	   * Get the dialog container.
17	   * SharedMoveDialog renders inside a Modal; the content div contains the
18	   * shared-move-dialog-folder-item rows which distinguish it from the private MoveDialog.
19	   */
20	  dialog(): Locator {
21	    return this.page.locator('.dialog-content').filter({
22	      has: this.page.locator('.move-dialog-folder-list'),
23	    });
24	  }
25	
26	  /**
27	   * Get the modal title element.
28	   */
29	  title(): Locator {
30	    return this.page.locator('.modal-title');
31	  }
32	
33	  /**
34	   * Get the folder list container (role="listbox").
