50	function sortItems(items: FolderChild[]): FolderChild[] {
51	  return [...items].sort((a, b) => {
52	    if (a.type === 'folder' && b.type !== 'folder') return -1;
53	    if (a.type !== 'folder' && b.type === 'folder') return 1;
