462	        {/* Error state */}
463	        {error && (
464	          <div className="shared-error" role="alert">
465	            <span>
466	              {'// ERROR: '}
467	              {error}
468	            </span>
469	          </div>
470	        )}
471	
472	        {/* Empty state */}
473	        {!isLoading && sharedItems.length === 0 && !error && (
474	          <div className="empty-state" data-testid="shared-empty-state">
475	            <div className="empty-state-content">
476	              <pre className="empty-state-ascii" aria-hidden="true">
477	                {sharedEmptyArt}
478	              </pre>
479	              <p className="empty-state-text">{'// NO SHARED ITEMS'}</p>
480	              <p className="empty-state-hint">
481	                ask others to share files using your public key from Settings
482	              </p>
483	            </div>
484	          </div>
485	        )}
486	
487	        {/* Shared items list */}
488	        {!isLoading && sharedItems.length > 0 && (
489	          <div className="file-list" role="grid">
490	            {/* Header row */}
491	            <div className="file-list-header" role="row">
492	              <div className="file-list-header-name" role="columnheader">
493	                [NAME]
494	              </div>
495	              <div className="file-list-header-shared-by" role="columnheader">
496	                [SHARED BY]
497	              </div>
498	              <div className="file-list-header-date" role="columnheader">
499	                [DATE]
500	              </div>
501	            </div>
502	
503	            {/* Item rows */}
504	            <div className="file-list-body" role="rowgroup">
505	              {sharedItems.map((sharedItem) => (
506	                <SharedListRow
507	                  key={sharedItem.share.shareId}
508	                  sharedItem={sharedItem}
509	                  onOpen={() => navigateToShare(sharedItem.share.shareId)}
510	                  onContextMenu={(e) => {
511	                    // Create a synthetic FolderChild for context menu
512	                    const fakeItem: FolderChild =
513	                      sharedItem.share.itemType === 'folder'
514	                        ? {
515	                            type: 'folder' as const,
516	                            id: sharedItem.share.shareId,
517	                            name: sharedItem.share.itemName,
518	                            ipnsName: sharedItem.share.ipnsName,
519	                            ipnsPrivateKeyEncrypted: '',
520	                            folderKeyEncrypted: '',
521	                            createdAt: Date.parse(sharedItem.share.createdAt),
522	                            modifiedAt: Date.parse(sharedItem.share.createdAt),
523	                          }
524	                        : {
525	                            type: 'file' as const,
526	                            id: sharedItem.share.shareId,
527	                            name: sharedItem.share.itemName,
528	                            fileMetaIpnsName: sharedItem.share.ipnsName,
529	                            createdAt: Date.parse(sharedItem.share.createdAt),
530	                            modifiedAt: Date.parse(sharedItem.share.createdAt),
531	                          };
532	                    handleSharedItemContextMenu(e, fakeItem, sharedItem.share.shareId);
533	                  }}
534	                />
535	              ))}
536	            </div>
537	          </div>
538	        )}
539	
540	        {/* Read-only context menu */}
541	        {contextMenu.visible && contextMenu.item && (
542	          <ContextMenu
543	            x={contextMenu.x}
544	            y={contextMenu.y}
545	            item={contextMenu.item}
546	            selectedCount={1}
547	            onClose={contextMenu.hide}
548	            onDownload={contextMenu.item.type === 'file' ? handleDownload : undefined}
549	            onRename={() => {}}
550	            onDelete={() => {}}
551	            onDetails={handleDetailsClick}
552	            readOnly
553	            onHide={contextShareId ? handleHide : undefined}
554	          />
555	        )}
556	
557	        {/* Details dialog */}
558	        <DetailsDialog
559	          open={detailsDialog.open}
560	          onClose={() => setDetailsDialog({ open: false, item: null })}
561	          item={detailsDialog.item}
562	          folderKey={null}
563	          parentFolderId=""
564	        />
565	      </div>
566	    );
567	  }
568	
569	  // Render folder view (inside a shared folder)
570	  const sortedChildren = sortItems(folderChildren);
571	  const hasChildren = folderChildren.length > 0;
572	
573	  return (
574	    <div
575	      className={`file-browser-content shared-browser${isDragOver ? ' shared-drag-over' : ''}`}
576	      onDragOver={handleDragOver}
577	      onDragLeave={handleDragLeave}
578	      onDrop={handleDrop}
579	    >
580	      {/* Toolbar with breadcrumbs and write actions */}
581	      <div className="file-browser-toolbar">
582	        <nav className="breadcrumb-nav" aria-label="Current location" data-testid="breadcrumbs">
583	          <span className="breadcrumb-prefix">~</span>
584	          <span className="breadcrumb-separator">/</span>
585	          <button type="button" className="breadcrumb-item" onClick={navigateToRoot}>
586	            shared
587	          </button>
588	          {breadcrumbs.map((crumb, index) => {
589	            const isLast = index === breadcrumbs.length - 1;
590	            return (
591	              <span key={crumb.id}>
592	                <span className="breadcrumb-separator">/</span>
593	                {isLast ? (
594	                  <span className="breadcrumb-item breadcrumb-item--current" aria-current="page">
595	                    {crumb.name.toLowerCase()}
596	                  </span>
597	                ) : (
598	                  <button
599	                    type="button"
600	                    className="breadcrumb-item"
601	                    onClick={() => navigateToBreadcrumb(breadcrumbs.indexOf(crumb))}
602	                  >
603	                    {crumb.name.toLowerCase()}
604	                  </button>
605	                )}
606	              </span>
607	            );
608	          })}
609	        </nav>
610	
611	        {/* Write toolbar -- only visible for write shares */}
612	        {isWritable && (
613	          <div className="file-browser-actions">
614	            <button
615	              type="button"
616	              className="toolbar-btn toolbar-btn--primary"
617	              onClick={handleUploadClick}
618	            >
619	              {'--upload'}
620	            </button>
621	            <button
622	              type="button"
623	              className="toolbar-btn toolbar-btn--primary"
624	              onClick={handleCreateFolderClick}
625	            >
626	              {'--mkdir'}
627	            </button>
628	            {/* Hidden file input for upload */}
629	            <input
630	              ref={fileInputRef}
631	              type="file"
632	              multiple
633	              style={{ display: 'none' }}
634	              onChange={handleFileSelected}
635	            />
636	          </div>
637	        )}
638	      </div>
639	
640	      {/* Selection action bar -- shown when items are selected in write shares.
641	          Only Move is wired for shared multi-select (phase 49); Download/Delete
642	          are intentionally omitted so the bar renders no no-op buttons. */}
643	      {isWritable && multiSelectActive && (
644	        <SelectionActionBar
645	          selectedItems={selectedItems}
646	          isLoading={isLoading}
647	          onClearSelection={clearSelection}
648	          onMove={handleBatchMoveClick}
649	        />
650	      )}
651	
652	      {/* Inline new folder input */}
653	      {showNewFolderInput && (
654	        <div className="shared-inline-input">
655	          <span className="shared-inline-input-label">{'> mkdir '}</span>
656	          <input
657	            ref={newFolderInputRef}
658	            type="text"
659	            className="shared-inline-input-field"
660	            value={newFolderName}
661	            onChange={(e) => setNewFolderName(e.target.value)}
662	            onKeyDown={handleCreateFolderKeyDown}
663	            onBlur={handleCreateFolderSubmit}
664	            placeholder="folder-name"
665	            aria-label="New folder name"
666	          />
667	        </div>
668	      )}
669	
670	      {/* Loading state */}
671	      {isLoading && (
672	        <div className="file-browser-loading">
673	          <span className="file-browser-loading-spinner">{'// loading...'}</span>
674	        </div>
675	      )}
676	
677	      {/* Error state */}
678	      {error && (
679	        <div className="shared-error" role="alert">
680	          <span>
681	            {'// ERROR: '}
682	            {error}
683	          </span>
684	        </div>
685	      )}
686	
687	      {/* File list */}
688	      {!isLoading && hasChildren && (
689	        <div className="file-list" role="grid">
690	          {/* Header row */}
691	          <div className="file-list-header" role="row">
692	            <div className="file-list-header-name" role="columnheader">
693	              [NAME]
694	            </div>
695	            <div className="file-list-header-size" role="columnheader">
696	              [SIZE]
697	            </div>
698	            <div className="file-list-header-date" role="columnheader">
699	              [MODIFIED]
700	            </div>
701	          </div>
702	
703	          {/* [..] PARENT_DIR row */}
704	          <div className="file-list-body" role="rowgroup">
705	            <div
706	              className="file-list-row file-list-row--parent"
707	              role="row"
708	              tabIndex={0}
709	              onDoubleClick={navigateUp}
710	              onKeyDown={(e) => {
711	                if (e.key === 'Enter' || e.key === ' ') {
712	                  e.preventDefault();
713	                  navigateUp();
714	                }
715	              }}
716	            >
717	              <div className="file-list-cell file-list-cell-name" role="gridcell">
718	                <span className="file-icon">{'<-'}</span>
719	                <span className="file-name">[..] PARENT_DIR</span>
720	              </div>
721	              <div className="file-list-cell file-list-cell-size" role="gridcell">
722	                --
723	              </div>
724	              <div className="file-list-cell file-list-cell-date" role="gridcell">
725	                --
726	              </div>
727	            </div>
728	
729	            {/* File/folder rows */}
730	            {sortedChildren.map((item) => (
731	              <SharedFolderRow
732	                key={item.id}
733	                item={item}
734	                permission={permission}
735	                isRenaming={renamingItem?.id === item.id}
736	                renameValue={renameValue}
737	                renameInputRef={renameInputRef}
738	                onRenameChange={setRenameValue}
739	                onRenameKeyDown={handleRenameKeyDown}
740	                onRenameSubmit={handleRenameSubmit}
741	                onContextMenu={(e) => handleContextMenu(e, item)}
742	                isSelected={selectedIds.has(item.id)}
743	                onSelect={(e) => handleSelect(item.id, e)}
744	                onDoubleClick={() => {
745	                  if (item.type === 'folder') {
746	                    navigateToSubfolder(item.id, item.name);
747	                  } else if (isFilePointer(item)) {
748	                    downloadSharedFile(item);
749	                  }
750	                }}
751	                onMoveItemTo={
752	                  isWritable
753	                    ? (destFolderId, destIpnsName, draggedItems) => {
754	                        // Route by what was actually dragged (not the current
755	                        // selection, nor the drop target). Resolve the dragged
756	                        // ids back to the current folder's children.
757	                        const draggedIds = new Set(draggedItems.map((d) => d.id));
758	                        const movedItems = sortedChildren.filter((c) => draggedIds.has(c.id));
759	                        if (movedItems.length === 0) return;
760	                        if (movedItems.length > 1) {
761	                          void batchMoveItems(
762	                            movedItems,
763	                            destFolderId,
764	                            destIpnsName,
765	                            clearSelection
766	                          );
767	                        } else {
768	                          void moveItem(movedItems[0], destFolderId, destIpnsName);
769	                        }
770	                      }
771	                    : undefined
772	                }
773	                selectedItems={selectedItems}
774	              />
775	            ))}
776	          </div>
777	        </div>
778	      )}
779	
780	      {/* Empty folder */}
781	      {!isLoading && !hasChildren && !error && (
782	        <div className="empty-state" data-testid="shared-empty-folder">
783	          <div className="empty-state-content">
784	            <pre className="empty-state-ascii" aria-hidden="true">
785	              {sharedEmptyArt}
786	            </pre>
787	            <p className="empty-state-text">{'// EMPTY SHARED FOLDER'}</p>
788	            <p className="empty-state-hint">
789	              {isWritable
790	                ? 'drag files here or use --upload'
791	                : 'this shared folder has no contents'}
792	            </p>
793	          </div>
794	        </div>
795	      )}
796	
797	      {/* Context menu -- conditional readOnly based on permission */}
798	      {contextMenu.visible && contextMenu.item && (
799	        <ContextMenu
800	          x={contextMenu.x}
801	          y={contextMenu.y}
802	          item={contextMenu.item}
803	          selectedCount={1}
804	          onClose={contextMenu.hide}
805	          onDownload={contextMenu.item.type === 'file' ? handleDownload : undefined}
806	          onEdit={
807	            contextMenu.item.type === 'file' && isTextFile(contextMenu.item.name)
808	              ? handleEditClick
809	              : undefined
810	          }
811	          onPreview={
812	            contextMenu.item.type === 'file' && isPreviewableFile(contextMenu.item.name)
813	              ? handlePreviewClick
814	              : undefined
815	          }
816	          onRename={isWritable ? handleRename : () => {}}
817	          onDelete={isWritable ? handleDelete : () => {}}
818	          onMove={
819	            isWritable && contextMenu.item?.type === 'file'
820	              ? () => handleMoveClick(contextMenu.item!)
821	              : undefined
822	          }
823	          onDetails={handleDetailsClick}
824	          readOnly={permission !== 'write'}
825	        />
826	      )}
827	
828	      {/* Move dialog -- shared subtree picker (folder view only) */}
829	      <SharedMoveDialog
830	        open={!!moveDialogItem}
831	        item={moveDialogItem}
832	        currentFolderId={breadcrumbs[breadcrumbs.length - 1]?.id ?? currentShareId ?? ''}
833	        shareId={currentShareId}
834	        onClose={() => setMoveDialogItem(null)}
835	        onConfirm={(destFolderId, destIpnsName) => {
836	          if (moveDialogItem) {
837	            void moveItem(moveDialogItem, destFolderId, destIpnsName);
838	          }
839	          setMoveDialogItem(null);
840	        }}
841	      />
842	
843	      {/* Batch move dialog -- opened from SelectionActionBar */}
844	      <SharedMoveDialog
845	        open={batchMoveDialogOpen}
846	        item={null}
847	        items={batchMoveItems_}
848	        currentFolderId={breadcrumbs[breadcrumbs.length - 1]?.id ?? currentShareId ?? ''}
849	        shareId={currentShareId}
850	        onClose={() => {
851	          setBatchMoveDialogOpen(false);
852	          setBatchMoveItems_([]);
853	        }}
854	        onConfirm={(destFolderId, destIpnsName) => {
855	          void batchMoveItems(batchMoveItems_, destFolderId, destIpnsName, clearSelection);
856	          setBatchMoveDialogOpen(false);
857	          setBatchMoveItems_([]);
858	        }}
859	      />
860	
861	      {/* Details dialog */}
862	      <DetailsDialog
863	        open={detailsDialog.open}
864	        onClose={() => setDetailsDialog({ open: false, item: null })}
865	        item={detailsDialog.item}
866	        folderKey={folderKey}
867	        parentFolderId=""
868	      />
869	
870	      {/* Text viewer dialog (read-only for read shares, editable for write shares) */}
871	      <TextEditorDialog
872	        open={editorDialog.open}
873	        onClose={() => {
874	          setEditorDialog({ open: false, item: null });
875	          // If viewing a standalone file share, go back to list on close
876	          if (currentView === 'file') {
877	            navigateToRoot();
878	          }
879	        }}
880	        item={editorDialog.item && isFilePointer(editorDialog.item) ? editorDialog.item : null}
881	        parentFolderId=""
882	        folderKey={folderKey}
883	        readOnly={!isWritable}
884	        shareId={currentShareId}
885	        onSaveSharedFile={isWritable ? updateSharedFile : undefined}
886	      />
887	
888	      {/* Image preview dialog */}
889	      <ImagePreviewDialog
890	        open={imagePreviewDialog.open}
891	        onClose={() => setImagePreviewDialog({ open: false, item: null })}
892	        item={
893	          imagePreviewDialog.item && isFilePointer(imagePreviewDialog.item)
894	            ? imagePreviewDialog.item
895	            : null
896	        }
897	        folderKey={folderKey}
898	        shareId={currentShareId}
899	      />
900	
901	      {/* PDF preview dialog */}
902	      <PdfPreviewDialog
903	        open={pdfPreviewDialog.open}
904	        onClose={() => setPdfPreviewDialog({ open: false, item: null })}
905	        item={
906	          pdfPreviewDialog.item && isFilePointer(pdfPreviewDialog.item)
907	            ? pdfPreviewDialog.item
908	            : null
909	        }
910	        folderKey={folderKey}
911	        shareId={currentShareId}
912	      />
913	
914	      {/* Audio player dialog */}
915	      <AudioPlayerDialog
916	        open={audioPlayerDialog.open}
917	        onClose={() => setAudioPlayerDialog({ open: false, item: null })}
918	        item={
919	          audioPlayerDialog.item && isFilePointer(audioPlayerDialog.item)
920	            ? audioPlayerDialog.item
921	            : null
922	        }
923	        folderKey={folderKey}
924	        shareId={currentShareId}
925	      />
926	
927	      {/* Video player dialog */}
928	      <VideoPlayerDialog
929	        open={videoPlayerDialog.open}
930	        onClose={() => setVideoPlayerDialog({ open: false, item: null })}
931	        item={
932	          videoPlayerDialog.item && isFilePointer(videoPlayerDialog.item)
933	            ? videoPlayerDialog.item
934	            : null
935	        }
936	        folderKey={folderKey}
937	        shareId={currentShareId}
938	      />
939	    </div>
940	  );
941	}
