2409	  async enumerateSharedSubtree(
2410	    shareId: string,
2411	    args: {
2412	      getShareKeysFn: (
2413	        shareId: string
2414	      ) => Promise<Array<{ keyType: string; itemId: string; encryptedKey: string }>>;
2415	      vaultPrivateKey: Uint8Array;
2416	    }
2417	  ): Promise<
2418	    Array<{
2419	      id: string;
2420	      name: string;
2421	      ipnsName: string;
2422	      writable: boolean;
2423	      parentId: string | null;
2424	    }>
2425	  > {
2426	    return this.withOperation('enumerateSharedSubtree', async () => {
2427	      const rootState = this.requireSharedFolder(shareId);
2428	      const shareKeys = await args.getShareKeysFn(shareId);
2429	
2430	      const result: Array<{
2431	        id: string;
2432	        name: string;
2433	        ipnsName: string;
2434	        writable: boolean;
2435	        parentId: string | null;
2436	      }> = [];
2437	      // visited keyed by ipnsName prevents cycles (a folder that references
2438	      // an ancestor's ipnsName would otherwise loop indefinitely)
2439	      const visited = new Set<string>([rootState.ipnsName]);
2440	      // `id` is the containing folder's id (null for the share root), threaded
2441	      // onto each node as `parentId` so the picker can exclude the moved
2442	      // folder's own subtree (a move into a descendant would cycle the tree).
2443	      const stack: Array<{
2444	        id: string | null;
2445	        ipnsName: string;
2446	        children: typeof rootState.children;
2447	      }> = [{ id: null, ipnsName: rootState.ipnsName, children: rootState.children }];
2448	
2449	      while (stack.length > 0) {
2450	        const current = stack.pop()!;
2451	        for (const child of current.children) {
2452	          if (child.type !== 'folder') continue;
2453	          if (visited.has(child.ipnsName)) continue;
2454	          visited.add(child.ipnsName);
2455	
2456	          // Require a read key — skip nodes the recipient cannot decrypt
2457	          const keyRecord = shareKeys.find((k) => k.keyType === 'folder' && k.itemId === child.id);
2458	          if (!keyRecord) continue;
2459	
2460	          const folderKey = await unwrapKey(
2461	            hexToBytes(keyRecord.encryptedKey),
2462	            args.vaultPrivateKey
2463	          );
2464	
2465	          try {
2466	            const writable = shareKeys.some(
2467	              (k) => k.keyType === 'folder-ipns' && k.itemId === child.id
2468	            );
2469	
2470	            result.push({
2471	              id: child.id,
2472	              name: child.name,
2473	              ipnsName: child.ipnsName,
2474	              writable,
2475	              parentId: current.id,
2476	            });
2477	
2478	            // Load children to continue DFS
2479	            const meta = await sdkCore.loadFolderMetadata({
2480	              ipnsName: child.ipnsName,
2481	              folderKey,
2482	              ctx: this.ctx,
2483	            });
2484	            if (meta?.metadata?.children) {
2485	              stack.push({
2486	                id: child.id,
2487	                ipnsName: child.ipnsName,
2488	                children: meta.metadata.children,
2489	              });
2490	            }
2491	          } finally {
2492	            // Zero the per-iteration folder key — never leave plaintext AES folder
2493	            // keys live in the heap across the DFS (caller owns vaultPrivateKey).
2494	            folderKey.fill(0);
2495	          }
2496	        }
2497	      }
2498	
2499	      return result;
2500	    });
2501	  }
2502	
2503	  // ---- BYO-IPFS pinning ----
2504	
2505	  /**
2506	   * Pin encrypted data according to the configured pinning mode.
2507	   * Returns { cid, size } regardless of mode.
2508	   *
2509	   * Mode behavior:
2510	   * - cipherbox: standard addToIpfs (default, unchanged)
2511	   * - external+Kubo: KuboProvider.pin() directly, NO CipherBox relay.
2512	   *   If Kubo unreachable, throws (no silent fallback).
2513	   * - external+PSA: CipherBox relay for CID acquisition (PSA is CID-reference-only),
2514	   *   then PSA pinByCid, then unpin from CipherBox.
2515	   * - dual: CipherBox primary (must succeed), external secondary (best-effort).
2516	   */
2517	  private async pinWithMode(
2518	    encryptedData: Uint8Array,
2519	    ctx: SdkContext,
2520	    onProgress?: ProgressCallback
2521	  ): Promise<{ cid: string; size: number; secondaryWarning?: string }> {
2522	    const mode = this.config.pinningConfig?.mode ?? 'cipherbox';
2523	
2524	    if (mode === 'cipherbox' || !this.externalProvider) {
2525	      // Default: upload via CipherBox API relay
2526	      const result = await sdkCore.addToIpfs(ctx, encryptedData, onProgress);
2527	      return { cid: result.cid, size: result.size };
2528	    }
2529	
2530	    if (mode === 'external') {
2531	      const ext = this.config.pinningConfig!.externalProvider!;
2532	
2533	      if (ext.protocol === 'kubo' || ext.protocol === 'pinata') {
2534	        // Direct upload to user's node -- NO CipherBox involvement at all.
2535	        // If node is unreachable, this throws. No silent fallback.
2536	        const result = await this.externalProvider.pin(encryptedData);
2537	        // Register CID with API for advisory tracking (best-effort — failure must not block upload)
2538	        try {
2539	          await sdkCore.registerCid(ctx, result.cid, result.size);
2540	        } catch {
2541	          // Advisory tracking failure is non-fatal — pin succeeded on external node
2542	        }
2543	        return { cid: result.cid, size: result.size };
2544	      }
2545	
2546	      // PSA: upload to CipherBox relay first (PSA can't accept raw data),
2547	      // then tell PSA to pin the CID, then unpin from CipherBox.
2548	      const relayResult = await sdkCore.addToIpfs(ctx, encryptedData, onProgress);
2549	      try {
2550	        await (this.externalProvider as sdkCore.PsaProvider).pinByCid(relayResult.cid);
2551	      } catch (err) {
2552	        // PSA pin failed, but data is still on CipherBox node
2553	        throw new Error(
2554	          `External PSA pin failed: ${err instanceof Error ? err.message : String(err)}. Data remains on CipherBox node.`
2555	        );
2556	      }
2557	      // PSA accepted the pin request -- unpin from CipherBox (async, best-effort)
2558	      sdkCore
2559	        .unpinFromIpfs(ctx, relayResult.cid)
2560	        .catch((err: unknown) =>
2561	          console.warn('[SDK] Unpin from CipherBox after PSA pin failed:', err)
