/**
 * Unit tests for collectChildKeys — the shared-folder descendant key collector.
 *
 * collectChildKeys walks folder metadata depth-first and re-wraps each
 * descendant's keys for a target public key (recipient or invite ephemeral key).
 * The behavior under test is WHICH keys it emits:
 *  - 'read'  → only the content keys (`file`, `folder`).
 *  - 'write' → additionally the IPNS signing keys (`file-ipns`, `folder-ipns`)
 *              so the recipient can write into / move items between owner-created
 *              descendants — but ONLY when the wrapped IPNS key is present.
 *
 * The crypto primitives and IPFS/IPNS/metadata services are mocked so the test
 * asserts the emitted ChildKeyDto[] (keyType / itemId / re-wrapped encryptedKey)
 * deterministically, with no real ECIES or network.
 *
 * The mocked reWrapEncryptedKey is the identity transform with an `rw:` prefix
 * (hexToBytes → unwrapKey → wrapKey → bytesToHex), so `reWrap('X') === 'rw:X'`.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import type { FolderChild, FilePointer, FolderEntry } from '@cipherbox/core';

// reWrapEncryptedKey (in the SUT module) = hexToBytes → unwrapKey → wrapKey →
// bytesToHex. Wiring these as identity-with-prefix makes the re-wrap output
// deterministic and assertable: reWrap('someHex') === 'rw:someHex'.
vi.mock('@cipherbox/crypto', () => ({
  hexToBytes: (hex: string) => new TextEncoder().encode(hex),
  bytesToHex: (bytes: Uint8Array) => `rw:${new TextDecoder().decode(bytes)}`,
  unwrapKey: vi.fn(async (bytes: Uint8Array) => bytes),
  wrapKey: vi.fn(async (plain: Uint8Array) => plain),
}));

const mockDecryptFolderMetadata = vi.fn();
vi.mock('@cipherbox/core', () => ({
  decryptFolderMetadata: (...args: unknown[]) => mockDecryptFolderMetadata(...args),
}));

const mockResolveFileMetadata = vi.fn();
vi.mock('../../services/file-metadata.service', () => ({
  resolveFileMetadata: (...args: unknown[]) => mockResolveFileMetadata(...args),
}));

const mockResolveIpnsRecord = vi.fn();
vi.mock('../../services/ipns.service', () => ({
  resolveIpnsRecord: (...args: unknown[]) => mockResolveIpnsRecord(...args),
}));

const mockFetchFromIpfs = vi.fn();
vi.mock('../api/ipfs', () => ({
  fetchFromIpfs: (...args: unknown[]) => mockFetchFromIpfs(...args),
}));

vi.mock('../logger', () => ({
  logger: { error: vi.fn(), warn: vi.fn(), info: vi.fn(), debug: vi.fn() },
}));

import { collectChildKeys } from './key-wrapping';
import type { ChildKeyDto } from '@cipherbox/api-client';

// --- fixtures ---------------------------------------------------------------

const OWNER_PRIV = new Uint8Array(32).fill(1);
const TARGET_PUB = new Uint8Array(65).fill(2);
const FOLDER_KEY = new Uint8Array(32).fill(3);

function makeFile(overrides: Partial<FilePointer> & { id: string; name: string }): FilePointer {
  return {
    type: 'file',
    fileMetaIpnsName: `k51meta-${overrides.id}`,
    createdAt: 1,
    modifiedAt: 1,
    ...overrides,
  } as FilePointer;
}

function makeFolder(
  overrides: Partial<FolderEntry> & { id: string; name: string }
): FolderEntry {
  return {
    type: 'folder',
    ipnsName: `k51sub-${overrides.id}`,
    ipnsPrivateKeyEncrypted: `folderIpnsHex-${overrides.id}`,
    folderKeyEncrypted: `folderKeyHex-${overrides.id}`,
    createdAt: 1,
    modifiedAt: 1,
    ...overrides,
  } as FolderEntry;
}

function byType(keys: ChildKeyDto[], keyType: string): ChildKeyDto[] {
  return keys.filter((k) => k.keyType === keyType);
}

beforeEach(() => {
  vi.clearAllMocks();
  // Each file's metadata yields a content key keyed off its IPNS name.
  mockResolveFileMetadata.mockImplementation(async (fileMetaIpnsName: string) => ({
    metadata: { fileKeyEncrypted: `fileKeyHex-${fileMetaIpnsName}` },
  }));
  // No recursion by default: folders resolve to "not found" so the subtree walk stops.
  mockResolveIpnsRecord.mockResolvedValue(null);
});

describe('collectChildKeys', () => {
  it('read permission: emits only content keys (file, folder), never IPNS keys', async () => {
    const children: FolderChild[] = [
      makeFile({ id: 'f1', name: 'a.txt', ipnsPrivateKeyEncrypted: 'fileIpnsHex-f1' }),
      makeFolder({ id: 'd1', name: 'sub' }),
    ];

    const keys = await collectChildKeys(children, FOLDER_KEY, OWNER_PRIV, TARGET_PUB, 'read', vi.fn());

    expect(byType(keys, 'file-ipns')).toHaveLength(0);
    expect(byType(keys, 'folder-ipns')).toHaveLength(0);

    const file = byType(keys, 'file')[0];
    expect(file).toMatchObject({
      keyType: 'file',
      itemId: 'f1',
      encryptedKey: 'rw:fileKeyHex-k51meta-f1',
    });
    const folder = byType(keys, 'folder')[0];
    expect(folder).toMatchObject({
      keyType: 'folder',
      itemId: 'd1',
      encryptedKey: 'rw:folderKeyHex-d1',
    });
  });

  it('write permission: also emits file-ipns and folder-ipns signing keys', async () => {
    const children: FolderChild[] = [
      makeFile({ id: 'f1', name: 'a.txt', ipnsPrivateKeyEncrypted: 'fileIpnsHex-f1' }),
      makeFolder({ id: 'd1', name: 'sub' }),
    ];

    const keys = await collectChildKeys(
      children,
      FOLDER_KEY,
      OWNER_PRIV,
      TARGET_PUB,
      'write',
      vi.fn()
    );

    expect(byType(keys, 'file-ipns')[0]).toMatchObject({
      keyType: 'file-ipns',
      itemId: 'f1',
      encryptedKey: 'rw:fileIpnsHex-f1',
    });
    expect(byType(keys, 'folder-ipns')[0]).toMatchObject({
      keyType: 'folder-ipns',
      itemId: 'd1',
      encryptedKey: 'rw:folderIpnsHex-d1',
    });
  });

  it('write permission: legacy file without a wrapped IPNS key stays read-only (no file-ipns)', async () => {
    // HKDF-derived legacy files have no ipnsPrivateKeyEncrypted (optional field).
    const children: FolderChild[] = [makeFile({ id: 'legacy', name: 'old.txt' })];

    const keys = await collectChildKeys(
      children,
      FOLDER_KEY,
      OWNER_PRIV,
      TARGET_PUB,
      'write',
      vi.fn()
    );

    expect(byType(keys, 'file')).toHaveLength(1);
    expect(byType(keys, 'file-ipns')).toHaveLength(0);
  });

  it('write permission: malformed folder without a wrapped IPNS key degrades to read-only, no throw', async () => {
    // Defends the guard added for the CodeRabbit review: ipnsPrivateKeyEncrypted is
    // typed required on FolderEntry, but folder metadata is decrypted from IPFS and
    // could be malformed/legacy. The folder content key is still emitted; folder-ipns
    // is skipped rather than crashing the whole share.
    const malformed = makeFolder({ id: 'bad', name: 'broken' });
    delete (malformed as Partial<FolderEntry>).ipnsPrivateKeyEncrypted;
    const children: FolderChild[] = [malformed];

    const keys = await collectChildKeys(
      children,
      FOLDER_KEY,
      OWNER_PRIV,
      TARGET_PUB,
      'write',
      vi.fn()
    );

    expect(byType(keys, 'folder')).toHaveLength(1);
    expect(byType(keys, 'folder-ipns')).toHaveLength(0);
  });

  it('recurses into subfolders depth-first, collecting nested descendant keys', async () => {
    const parent = makeFolder({ id: 'd1', name: 'sub' });
    const nestedFile = makeFile({ id: 'n1', name: 'nested.txt', ipnsPrivateKeyEncrypted: 'fileIpnsHex-n1' });

    // The parent folder resolves to a CID whose decrypted metadata holds nestedFile.
    mockResolveIpnsRecord.mockImplementation(async (ipnsName: string) =>
      ipnsName === parent.ipnsName ? { cid: 'cid-sub' } : null
    );
    mockFetchFromIpfs.mockResolvedValue(new TextEncoder().encode('{}'));
    mockDecryptFolderMetadata.mockResolvedValue({ children: [nestedFile] });

    const keys = await collectChildKeys(
      [parent],
      FOLDER_KEY,
      OWNER_PRIV,
      TARGET_PUB,
      'write',
      vi.fn()
    );

    // Parent folder keys + the nested file's keys (write → content + ipns).
    expect(byType(keys, 'folder').map((k) => k.itemId)).toContain('d1');
    expect(byType(keys, 'folder-ipns').map((k) => k.itemId)).toContain('d1');
    expect(byType(keys, 'file').map((k) => k.itemId)).toContain('n1');
    expect(byType(keys, 'file-ipns').map((k) => k.itemId)).toContain('n1');
  });

  it('reports progress once per re-wrapped key', async () => {
    const onProgress = vi.fn();
    const children: FolderChild[] = [
      makeFile({ id: 'f1', name: 'a.txt', ipnsPrivateKeyEncrypted: 'fileIpnsHex-f1' }),
      makeFolder({ id: 'd1', name: 'sub' }),
    ];

    const keys = await collectChildKeys(children, FOLDER_KEY, OWNER_PRIV, TARGET_PUB, 'write', onProgress);

    // file + file-ipns + folder + folder-ipns = 4 keys, 4 progress ticks.
    expect(keys).toHaveLength(4);
    expect(onProgress).toHaveBeenCalledTimes(4);
  });

  it('continues past a file whose metadata resolution fails (per-child error isolation)', async () => {
    mockResolveFileMetadata.mockImplementation(async (fileMetaIpnsName: string) => {
      if (fileMetaIpnsName === 'k51meta-bad') throw new Error('IPNS resolve failed');
      return { metadata: { fileKeyEncrypted: `fileKeyHex-${fileMetaIpnsName}` } };
    });
    const children: FolderChild[] = [
      makeFile({ id: 'bad', name: 'bad.txt' }),
      makeFile({ id: 'ok', name: 'ok.txt' }),
    ];

    const keys = await collectChildKeys(children, FOLDER_KEY, OWNER_PRIV, TARGET_PUB, 'read', vi.fn());

    // The failing child is skipped; the healthy one still yields its key.
    expect(byType(keys, 'file').map((k) => k.itemId)).toEqual(['ok']);
  });
});

