export const meta = {
  name: 'verify-phases-47-49',
  description: 'Goal-backward verification of phases 47-49 with adversarial cross-check',
  phases: [
    { title: 'Verify', detail: 'gsd-verifier goal-backward analysis per phase' },
    { title: 'Adversarial', detail: 'skeptic refutes each verifier verdict' },
  ],
};

const PHASES = [
  { num: '47', dir: '.planning/phases/47-sdk-folder-state-publish-consolidation' },
  { num: '48', dir: '.planning/phases/48-sdk-self-bootstrap-regression-fix-and-shared-folder-metadata' },
  { num: '49', dir: '.planning/phases/49-shared-folder-move-intra-share-and-usefoldernavigation-unwra' },
];

// Central behavioral evidence (test suites run once by the orchestrator to avoid
// concurrent-suite RAM starvation) is injected via args.behavioral.
const BEHAVIORAL = (args && args.behavioral) || 'No central behavioral evidence supplied.';

const VERIFY_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['phase', 'status', 'score', 'truths', 'gaps', 'human_items', 'report_path'],
  properties: {
    phase: { type: 'string' },
    status: { type: 'string', enum: ['passed', 'gaps_found', 'human_needed'] },
    score: { type: 'string', description: 'verified_truths / total_truths, e.g. "6/6"' },
    truths: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['text', 'status', 'evidence'],
        properties: {
          text: { type: 'string' },
          status: { type: 'string', enum: ['VERIFIED', 'FAILED', 'UNCERTAIN'] },
          evidence: { type: 'string', description: 'file:line or command proving it' },
        },
      },
    },
    artifacts_summary: { type: 'string' },
    key_links_summary: { type: 'string' },
    anti_patterns: { type: 'string' },
    test_quality: { type: 'string' },
    gaps: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['severity', 'description'],
        properties: {
          severity: { type: 'string', enum: ['blocker', 'warning', 'info'] },
          description: { type: 'string' },
          fix: { type: 'string' },
        },
      },
    },
    human_items: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['name', 'what', 'expected'],
        properties: {
          name: { type: 'string' },
          what: { type: 'string' },
          expected: { type: 'string' },
        },
      },
    },
    deferred: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['item', 'covered_by'],
        properties: { item: { type: 'string' }, covered_by: { type: 'string' } },
      },
    },
    report_path: { type: 'string' },
  },
};

const ADV_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['phase', 'reviewed_truths', 'overturns', 'spurious_gaps', 'confidence', 'adjusted_status', 'notes'],
  properties: {
    phase: { type: 'string' },
    reviewed_truths: { type: 'number' },
    overturns: {
      type: 'array',
      description: 'Truths the verifier marked VERIFIED that are actually stub/unwired/over-claimed',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['truth', 'verifier_said', 'reviewer_finds', 'evidence'],
        properties: {
          truth: { type: 'string' },
          verifier_said: { type: 'string' },
          reviewer_finds: { type: 'string' },
          evidence: { type: 'string' },
        },
      },
    },
    spurious_gaps: {
      type: 'array',
      description: 'Gaps the verifier raised that are NOT real (already covered / misread)',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['gap', 'why_not_real'],
        properties: { gap: { type: 'string' }, why_not_real: { type: 'string' } },
      },
    },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    adjusted_status: { type: 'string', enum: ['passed', 'gaps_found', 'human_needed'] },
    notes: { type: 'string' },
  },
};

function verifyPrompt(p) {
  return `You are running GSD verify-phase for **Phase ${p.num}** of the CipherBox project. Follow the workflow at \`.claude/gsd-core/workflows/verify-phase.md\` precisely (goal-backward verification: task completion != goal achievement).

CONTEXT:
- We are on the \`main\` branch AFTER PR #509 merged, so phases 47, 48 and 49 are all fully merged into the working tree. Verify against the CURRENT codebase.
- Phase directory: \`${p.dir}\`
- The phase contract is the aggregated \`must_haves\` frontmatter (truths / artifacts / key_links) across \`${p.dir}/${p.num}-*-PLAN.md\`. Extract it with:
  \`node .claude/gsd-core/bin/gsd-tools.cjs query frontmatter.get <plan> --field must_haves\`
  and the artifact/key-link verifiers:
  \`node .claude/gsd-core/bin/gsd-tools.cjs query verify.artifacts <plan>\`
  \`node .claude/gsd-core/bin/gsd-tools.cjs query verify.key-links <plan>\`
- The SUMMARY files (\`${p.dir}/${p.num}-*-SUMMARY.md\`) list what was actually built and the files touched.

DO THE FULL GOAL-BACKWARD VERIFICATION:
1. Establish must-haves (truths/artifacts/key_links) from PLAN frontmatter; if absent, derive from the phase goal in ROADMAP.
2. Verify each TRUTH against the real code: identify supporting artifacts, check they exist + are substantive (not stubs) + are WIRED (imported AND used). Cite file:line evidence.
3. Verify artifacts at all 3 levels and key links (wired / partial / not_wired).
4. Requirements coverage (if .planning/REQUIREMENTS.md references this phase).
5. CONTEXT.md decision coverage (non-blocking) if a ${p.num}-CONTEXT.md exists.
6. Anti-pattern scan on the phase's modified files (TBD/FIXME/XXX without issue ref = blocker; TODO/HACK = warning; placeholder = blocker).
7. Test-quality audit — STATIC ONLY: grep the phase's test files for skipped/disabled tests on requirements, circular fixtures, and weak assertions. Classify assertion strength.
8. Human-verification items: if this is an infra/SDK/foundation phase with no user-facing surface, mark N/A — do NOT invent manual steps. Phase 49 has a user-facing web move flow, so genuine UI items are allowed.
9. Determine status (gaps_found > human_needed > passed), then filter deferred items against later milestone phases.

CRITICAL EXECUTION CONSTRAINT:
- Do **NOT** run the full test suite or any broad \`pnpm test\` / \`vitest run\` / \`jest\` across packages. Three verifiers run concurrently and parallel suites starve RAM. Behavioral test evidence has already been gathered centrally and is provided below — treat it as the behavioral result. You MAY run a SINGLE targeted check (one \`tsc -b\`, one specific test file, or grep) ONLY if essential to resolve one truth.

CENTRAL BEHAVIORAL EVIDENCE (already run by the orchestrator):
${BEHAVIORAL}

OUTPUT:
- WRITE the report to \`${p.dir}/${p.num}-VERIFICATION.md\` following \`.claude/gsd-core/templates/verification-report.md\` (overwrite the existing planning-time file). Use Write/Bash to create it.
- THEN return the StructuredOutput verdict. Set report_path to the file you wrote. Be honest: mark a truth VERIFIED only with concrete file:line evidence; otherwise FAILED or UNCERTAIN.`;
}

function adversarialPrompt(p, verdict) {
  return `You are an ADVERSARIAL verifier auditing a GSD verification verdict for **Phase ${p.num}** of CipherBox (on \`main\`, post-merge). Your job is to REFUTE, not agree. Default to skepticism: a truth is only truly VERIFIED if you can independently confirm the artifact exists, is substantive, AND is wired into a real call path.

The first-pass verifier produced this verdict (status=${verdict.status}, score=${verdict.score}) and wrote ${verdict.report_path}:

TRUTHS CLAIMED:
${(verdict.truths || []).map((t, i) => `${i + 1}. [${t.status}] ${t.text}\n   evidence: ${t.evidence}`).join('\n')}

GAPS RAISED:
${(verdict.gaps || []).map((g) => `- (${g.severity}) ${g.description}`).join('\n') || '(none)'}

YOUR TASK:
- For each truth marked VERIFIED, try to OVERTURN it: open the cited file:line, confirm the symbol really exists and is non-trivial, and grep that it is actually imported AND called from a real path (not just defined, not only referenced in tests). If the evidence is a stub, dead export, or unwired, record an overturn with your own file:line evidence.
- Check the GAPS raised: is any of them spurious (already handled elsewhere / misread)? Record spurious_gaps.
- Pay special attention to Phase ${p.num}'s riskiest claims: ${p.num === '47' ? 'the single publishWithCas owning CAS/409/merge for BOTH file and folder paths, and the prunedCids pin-leak fix actually being called.' : p.num === '48' ? 'loadFolder keeping the fresher folderTree entry (no stale overwrite) AND still resolving genuinely-absent folders (no #498 regression).' : 'the moved file staying decryptable for BOTH owner and recipient (FileMetadata re-encrypted source→dest folderKey), and write-key distribution reaching owner-created descendants.'}
- Read the codebase directly (Read/Grep/Glob/Bash). Do NOT run broad test suites (RAM). A single grep/tsc/targeted file read is fine.
- Conclude with an adjusted_status. If you found a real overturn of a goal-critical truth, adjusted_status must be gaps_found. If the verifier was sound, confirm its status.

Return the StructuredOutput verdict. Be specific and evidence-backed; vague suspicion is not an overturn.`;
}

phase('Verify');
const results = await pipeline(
  PHASES,
  (p) =>
    agent(verifyPrompt(p), {
      agentType: 'gsd-verifier',
      label: `verify:${p.num}`,
      phase: 'Verify',
      schema: VERIFY_SCHEMA,
    }),
  (verdict, p) => {
    if (!verdict) return { phase: p.num, verdict: null, adv: null };
    return agent(adversarialPrompt(p, verdict), {
      label: `adversary:${p.num}`,
      phase: 'Adversarial',
      schema: ADV_SCHEMA,
      effort: 'high',
    }).then((adv) => ({ phase: p.num, verdict, adv }));
  }
);

return results.filter(Boolean);

